contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        c.depositsCount(); if (__ESBMC_reverted()) return; // no-op read? not allowed? remove?
        uint preBalance = address(c).balance;
        uint preCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        require(value <= preBalance);
        c.withdraw(value); if (__ESBMC_reverted()) return;
        uint postBalance = address(c).balance;
        uint postCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(postBalance + value == preBalance && postCount == preCount);
    }

    receive() external payable {}
}

