// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.depositsCount() {} catch { return; }
        uint preBalance = address(c).balance;
        uint256 preCount;
        try c.depositsCount() returns (uint256 __r) { preCount = __r; } catch { return; }
        vm.assume(value <= preBalance);
        try c.withdraw(value) {} catch { return; }
        uint postBalance = address(c).balance;
        uint256 postCount;
        try c.depositsCount() returns (uint256 __r) { postCount = __r; } catch { return; }
        assertTrue(postBalance + value == preBalance && postCount == preCount);
    }

    function testFuzz_run(uint256 amount, uint256 value) public {
        _run(amount, value);
    }

    receive() external payable {}
}
